import itertools

# Helper to format minutes since midnight into 12‑hour time string
def fmt(t):
    h = (t // 60) % 24
    m = t % 60
    suffix = "AM" if h < 12 else "PM"
    h12 = h % 12
    if h12 == 0:
        h12 = 12
    return f"{h12}:{m:02d}{suffix}"

# Travel times (minutes) as given
travel = {
    "Embarcadero": {
        "Richmond District": 21, "Union Square": 10, "Financial District": 5,
        "Pacific Heights": 11, "Nob Hill": 10, "Bayview": 21,
