# Friend data: name, location, window start, window end, required meeting minutes
friends = [
    {"name": "Kenneth", "loc": "Richmond District",
     "start": 21*60+15, "end": 22*60, "need": 30},
    {"name": "Lisa", "loc": "Union Square",
     "start": 9*60, "end": 16*60+30, "need": 45},
    {"name": "Joshua", "loc": "Financial District",
     "start": 12*60, "end": 15*60+15, "need": 15},
    {"name": "Nancy", "loc": "Pacific Heights",
     "start": 8*60, "end": 11*60+30, "need": 90},
    {"name": "Andrew", "loc": "Nob Hill",
     "start": 11*60+30, "end": 20*60+15, "need": 60},
    {"name": "John", "loc": "Bayview",
     "start": 16*60+45, "end": 21*60+30, "need": 75},
]

# Map location name to friend list for quick lookup (not required but handy)
friend_by_name = {f["name"]: f for f in friends}

best_schedule = []
best_count = -1

def dfs(cur_loc, cur_time, visited, steps):
    global best_schedule, best_count
    # Update best if we have visited more friends
    if len(visited) > best_count:
        best_count = len(visited)
        best_schedule = steps[:]

    for f in friends:
        if f["name"] in visited:
            continue
        travel_time = travel[cur_loc][f["loc"]]
        arrival = cur_time + travel_time
        meet_start = max(arrival, f["start"])
        meet_end = meet_start + f["need"]
        if meet_end <= f["end"]:
            # Build step strings
            new_steps = steps[:]
            new_steps.append(
                f"You travel to {f['loc']} in {travel_time} minutes and arrive at {fmt(arrival)}."
            )
            if arrival < meet_start:
                new_steps.append(
                    f"You wait until {fmt(meet_start)}."
                )
            new_steps.append(
                f"You meet {f['name']} from {fmt(meet_start)} to {fmt(meet_end)}."
            )
            dfs(f["loc"], meet_end, visited | {f["name"]}, new_steps)

# Start itinerary
start_time = 9*60  # 9:00 AM
initial_steps = [f"You start at Embarcadero at {fmt(start_time)}."]
dfs("Embarcadero", start_time, set(), initial_steps)

